#include "bootbutton.h"

// Compile-time regression checks: exercise the real state machine using the
// installed ESP32 compiler as well as the optional host test suite. No runtime
// code or hardware access is generated by these checks.
namespace {
using B = BootButton;
constexpr B::Action edge(B &b, bool pressed, uint32_t t) {
  b.update(pressed, t);
  return b.update(pressed, t + B::DEBOUNCE_MS);
}
constexpr bool singleWait() {
  B b; b.begin(false, 0); edge(b, true, 100); edge(b, false, 200);
  return b.active() && b.update(false, 549) == B::NONE &&
         b.update(false, 550) == B::SINGLE && b.update(false, 900) == B::NONE && !b.active();
}
constexpr bool doubleOnly() {
  B b; b.begin(false, 0); edge(b, true, 100); edge(b, false, 200); edge(b, true, 400);
  return edge(b, false, 500) == B::DOUBLE && b.update(false, 1000) == B::NONE;
}
constexpr bool doubleBoundary() {
  B b; b.begin(false, 0); edge(b, true, 100); edge(b, false, 200);
  return b.update(true, 550) == B::NONE && b.update(true, 575) == B::NONE &&
         edge(b, false, 650) == B::DOUBLE && b.update(false, 1200) == B::NONE;
}
constexpr bool lateSecond() {
  B b; b.begin(false, 0); edge(b, true, 100); edge(b, false, 200);
  return b.update(true, 551) == B::NONE && b.update(true, 576) == B::SINGLE &&
         edge(b, false, 650) == B::NONE && b.update(false, 1000) == B::SINGLE;
}
constexpr bool longOnly() {
  B b; b.begin(false, 0); edge(b, true, 100);
  return b.update(true, 1599) == B::NONE && b.update(true, 1600) == B::LONG &&
         b.update(true, 3000) == B::NONE && edge(b, false, 3100) == B::NONE &&
         b.update(false, 4000) == B::NONE;
}
constexpr bool secondLong() {
  B b; b.begin(false, 0); edge(b, true, 100); edge(b, false, 200); edge(b, true, 400);
  return b.update(true, 600) == B::NONE && b.update(true, 1900) == B::LONG &&
         edge(b, false, 2000) == B::NONE && b.update(false, 3000) == B::NONE;
}
constexpr bool longRelease() {
  B b; b.begin(false, 0); edge(b, true, 100);
  return edge(b, false, 1700) == B::LONG && b.update(false, 2500) == B::NONE;
}
constexpr bool bounce() {
  B b; b.begin(false, 0);
  return b.update(true, 100) == B::NONE && b.update(false, 110) == B::NONE &&
         b.update(true, 120) == B::NONE && b.update(true, 144) == B::NONE &&
         b.update(true, 145) == B::NONE && b.update(false, 200) == B::NONE &&
         b.update(true, 210) == B::NONE && b.update(false, 220) == B::NONE &&
         b.update(false, 245) == B::NONE && b.update(false, 569) == B::NONE &&
         b.update(false, 570) == B::SINGLE;
}
constexpr bool heldAtBegin() {
  B b; b.begin(true, 0);
  return b.update(true, 2000) == B::NONE && edge(b, false, 2200) == B::NONE &&
         b.update(false, 3000) == B::NONE && edge(b, true, 3100) == B::NONE &&
         edge(b, false, 3200) == B::NONE && b.update(false, 3550) == B::SINGLE;
}
constexpr bool rolloverSingleLong() {
  B b; uint32_t t = 0xFFFFFF00u; b.begin(false, t);
  edge(b, true, t + 10); edge(b, false, t + 100);
  if (b.update(false, t + 449) != B::NONE || b.update(false, t + 450) != B::SINGLE) return false;
  edge(b, true, t + 500);
  return b.update(true, t + 1999) == B::NONE && b.update(true, t + 2000) == B::LONG;
}
constexpr bool rolloverDouble() {
  B b; uint32_t t = 0xFFFFFF00u; b.begin(false, t);
  edge(b, true, t + 10); edge(b, false, t + 100); edge(b, true, t + 400);
  return edge(b, false, t + 500) == B::DOUBLE && b.update(false, t + 1000) == B::NONE;
}
constexpr bool belowLongThreshold() {
  B b; b.begin(false, 0); edge(b, true, 100);
  return edge(b, false, 1599) == B::NONE && b.update(false, 1949) == B::SINGLE;
}
static_assert(singleWait(), "single must wait 350ms after release");
static_assert(doubleOnly(), "double must suppress single");
static_assert(doubleBoundary(), "second edge at 350ms must be accepted");
static_assert(lateSecond(), "second edge after 350ms is two singles");
static_assert(longOnly(), "long must fire once at 1500ms without single");
static_assert(secondLong(), "long second press must override pending click");
static_assert(longRelease(), "long must be recognised on late release");
static_assert(bounce(), "both edges must be debounced");
static_assert(heldAtBegin(), "ignore BOOT held during handler init");
static_assert(rolloverSingleLong(), "single and long must survive millis wrap");
static_assert(rolloverDouble(), "double must survive millis wrap");
static_assert(belowLongThreshold(), "1499ms is not a long press");
}  // namespace
